import pandas as pd
from sklearn.model_selection import train_test_split
from sklearn.linear_model import LinearRegression


def task_func(df, col_a='A', col_b='B', col_c='C', seed=None):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None

    required_cols = [col_a, col_b, col_c]
    if any(col not in df.columns for col in required_cols):
        return None

    # Validate and coerce all required columns to numeric
    try:
        numeric_df = pd.DataFrame({
            col: pd.to_numeric(df[col], errors='coerce')
            for col in required_cols
        })
    except Exception:
        return None

    # If any required value is non-numeric or missing, reject the input
    if numeric_df.isna().any().any():
        return None

    # Filter rows based on the specified conditions
    filtered_df = numeric_df[(numeric_df[col_b] > 50) & (numeric_df[col_c] == 900)]
    if filtered_df.empty:
        return None

    # Need enough data to split and train
    if len(filtered_df) < 2:
        return None

    X = filtered_df[[col_a]]
    y = filtered_df[col_b]

    try:
        X_train, X_test, y_train, y_test = train_test_split(
            X,
            y,
            test_size=0.2,
            random_state=seed,
        )
    except Exception:
        return None

    if X_train.empty or X_test.empty:
        return None

    model = LinearRegression()
    try:
        model.fit(X_train, y_train)
        predictions = model.predict(X_test)
    except Exception:
        return None

    return predictions, model
