import os
import glob
from uuid import uuid4

def task_func(directory_path):
    files = [
        name
        for name in sorted(os.listdir(directory_path))
        if os.path.isfile(os.path.join(directory_path, name))
    ]

    def reverse_words(filename):
        return ".".join(reversed(filename.split(".")))

    temp_paths = {}
    new_names = {name: reverse_words(name) for name in files}

    # First pass: move every file to a unique temporary name to avoid collisions.
    for name in files:
        src = os.path.join(directory_path, name)
        temp_name = f".__tmp_reverse_{uuid4().hex}__"
        temp_path = os.path.join(directory_path, temp_name)
        while os.path.exists(temp_path):
            temp_name = f".__tmp_reverse_{uuid4().hex}__"
            temp_path = os.path.join(directory_path, temp_name)
        os.replace(src, temp_path)
        temp_paths[name] = temp_path

    # Second pass: rename temporary files to their final reversed names.
    new_filenames = []
    for name in files:
        dst_name = new_names[name]
        dst = os.path.join(directory_path, dst_name)
        os.replace(temp_paths[name], dst)
        new_filenames.append(dst_name)

    return new_filenames
