import re
from pathlib import Path
import tarfile
import uuid

# Constants
PATTERN = r"(?<!Distillr)\\\\AcroTray\.exe"
DIRECTORY = r"C:\\SomeDir\\"

def task_func(directory=DIRECTORY, file_pattern=PATTERN):
    fs_directory = re.sub(r"\\{2,}", r"\\", directory)
    root = Path(fs_directory)
    regex = re.compile(file_pattern)

    matched_files = []
    if root.exists() and root.is_dir():
        for path in root.rglob("*"):
            if path.is_file():
                candidate = str(path).replace("\\", "\\\\")
                if regex.search(candidate):
                    matched_files.append(path)

    archive_path = Path.cwd() / f"acrotray_matches_{uuid.uuid4().hex}.tar"
    with tarfile.open(archive_path, "w") as tar:
        for path in sorted(matched_files):
            try:
                arcname = path.relative_to(root)
            except ValueError:
                arcname = path.name
            tar.add(path, arcname=str(arcname).replace("\\", "/"))

    return str(archive_path)


if __name__ == "__main__":
    print(task_func())
