import urllib.request
from lxml import etree
import pandas as pd
from io import BytesIO


def task_func(url):
    try:
        with urllib.request.urlopen(url) as response:
            xml_data = response.read()
    except Exception as exc:
        raise ValueError("Unable to fetch XML from URL.") from exc

    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, recover=False)
        root = etree.fromstring(xml_data, parser=parser)
    except (etree.XMLSyntaxError, ValueError, TypeError) as exc:
        raise ValueError("Invalid XML syntax.") from exc

    def local_name(element):
        return etree.QName(element).localname

    items = [elem for elem in root.iter() if local_name(elem) == "item"]
    if not items:
        raise ValueError("XML structure does not match expected format.")

    records = []
    for item in items:
        record = {}
        children = [child for child in item if isinstance(child.tag, str)]

        for child in children:
            if len(child):
                raise ValueError("XML structure does not match expected format.")

            key = local_name(child)
            if key in record:
                raise ValueError("XML structure does not match expected format.")

            value = child.text.strip() if child.text is not None and child.text.strip() != "" else None
            record[key] = value

        records.append(record)

    return pd.DataFrame(records)
