        **{
            abbr.lower(): i
            for i, abbr in enumerate(
                ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
                start=1,
            )
        },
    }

    def to_dataframe(obj):
        if isinstance(obj, pd.DataFrame):
            return obj.copy()
        if isinstance(obj, pd.Series):
            df = obj.reset_index()
            if df.shape[1] == 2:
                df.columns = ["month", obj.name if obj.name is not None else "value"]
            return df
        return pd.DataFrame(obj)

    def pick_column(columns, *candidates):
        lowered = {str(c).strip().lower(): c for c in columns}
        for cand in candidates:
            if cand in lowered:
                return lowered[cand]
        return None

    def infer_year_from_series(series):
        if series is None:
            return None
        numeric = pd.to_numeric(series, errors="coerce")
        numeric = numeric.dropna()
        if not numeric.empty:
            return int(numeric.iloc[0])

        dt = pd.to_datetime(series, errors="coerce")
        if hasattr(dt, "dt"):
            years = dt.dt.year.dropna().unique()
            if len(years) > 0:
                return int(years[0])
        return None

    def parse_month_source(series):
        s = pd.Series(series).reset_index(drop=True)

        numeric = pd.to_numeric(s, errors="coerce")
        if numeric.notna().all():
            ints = numeric.astype(int)
            if ints.between(1, 12).all():
                labels = [month_full_names[i - 1] for i in ints]
                return ints, labels, None

        lowered = s.astype(str).str.strip().str.lower()
        mapped = lowered.map(month_lookup)
        if mapped.notna().all():
            ints = mapped.astype(int)
            labels = [month_full_names[i - 1] for i in ints]
            return ints, labels, None

        dt = pd.to_datetime(s, errors="coerce")
        if dt.notna().any():
            order = dt.dt.month
            labels = order.map(lambda m: month_full_names[int(m) - 1] if pd.notna(m) else None)
            years = dt.dt.year.dropna().unique()
            year = int(years[0]) if len(years) else None
            return order, labels.tolist(), year

        return None, s.astype(str).tolist(), None

    df = to_dataframe(data)

    fig, ax = plt.subplots()

    if df.empty:
        title_year = datetime.now().year
        ax.set_title(f"Monthly Data for {title_year}")
        ax.set_xlabel("Month")
        ax.set_ylabel("Value")
        return ax

    month_col = pick_column(df.columns, "month")
    value_col = pick_column(df.columns, "value")
    year_col = pick_column(df.columns, "year")
    date_col = pick_column(df.columns, "date", "datetime", "timestamp", "time")

    # Resolve month source
    month_source = None
    if month_col is not None:
        month_source = df[month_col]
    elif date_col is not None:
        month_source = df[date_col]
    elif isinstance(df.index, pd.DatetimeIndex):
        month_source = pd.Series(df.index)
    else:
        month_source = pd.Series(df.index)

    # Resolve value source
    if value_col is None:
        preferred_cols = [
            c for c in df.columns
            if c not in {month_col, year_col, date_col}
        ]
        numeric_candidates = [c for c in preferred_cols if pd.api.types.is_numeric_dtype(df[c])]
        value_col = numeric_candidates[0] if numeric_candidates else (preferred_cols[0] if preferred_cols else df.columns[0])

    values = pd.to_numeric(df[value_col], errors="coerce")

    order, labels, year_from_month = parse_month_source(month_source)

    # Determine year for the title
    year = None
    if year_col is not None:
        year = infer_year_from_series(df[year_col])
    if year is None and year_from_month is not None:
        year = year_from_month
    if year is None and date_col is not None:
        year = infer_year_from_series(df[date_col])
    if year is None and isinstance(df.index, pd.DatetimeIndex):
        years = pd.Index(df.index.year).dropna().unique()
        if len(years) > 0:
            year = int(years[0])
    if year is None:
        year = datetime.now().year

    plot_df = pd.DataFrame({"month": labels, "value": values})
    if order is not None:
        plot_df["_order"] = order
        plot_df = plot_df.sort_values("_order", kind="stable")

    plot_df = plot_df.dropna(subset=["month", "value"])

    ax.bar(plot_df["month"], plot_df["value"])
    ax.set_title(f"Monthly Data for {year}")
    ax.set_xlabel("Month")
    ax.set_ylabel("Value")

    return ax
