import os
import json
from collections import Counter


def task_func(json_files_path='./json_files/', key='name'):
    """
    Count occurrences of values for a specified key across all JSON files in a directory.

    Args:
        json_files_path (str): Path to a directory containing JSON files.
        key (str): Key whose values should be counted.

    Returns:
        dict: A dictionary mapping each distinct value of `key` to its count.
    """
    counts = Counter()

    def _make_hashable(value):
        try:
            hash(value)
            return value
        except TypeError:
            # Fallback for unhashable values such as lists/dicts.
            return json.dumps(value, sort_keys=True, ensure_ascii=False)

    def _process_json_obj(obj):
        if isinstance(obj, dict):
            if key in obj:
                counts[_make_hashable(obj[key])] += 1
        elif isinstance(obj, list):
            for item in obj:
                _process_json_obj(item)

    # Support either a directory of JSON files or a single JSON file path.
    paths = []
    if os.path.isfile(json_files_path):
        if json_files_path.lower().endswith('.json'):
            paths = [json_files_path]
    elif os.path.isdir(json_files_path):
        try:
            for filename in os.listdir(json_files_path):
                if filename.lower().endswith('.json'):
                    full_path = os.path.join(json_files_path, filename)
                    if os.path.isfile(full_path):
                        paths.append(full_path)
        except OSError:
            return {}
    else:
        return {}

    for file_path in paths:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            _process_json_obj(data)
        except (OSError, json.JSONDecodeError, UnicodeDecodeError):
            continue

    return dict(counts)
