    s2 = data[col2]

    if not _is_categorical(s1) or not _is_categorical(s2):
        raise TypeError("Both columns must contain categorical data")

    subset = data[[col1, col2]].dropna()
    if subset.empty:
        raise ValueError("Insufficient non-missing data")

    if subset[col1].nunique() < 2 or subset[col2].nunique() < 2:
        raise ValueError("Both columns must have multiple categories")

    counts1 = subset[col1].value_counts()
    counts2 = subset[col2].value_counts()

    if (counts1 < 5).any() or (counts2 < 5).any():
        raise ValueError("Each category must have at least 5 observations")

    contingency = pd.crosstab(subset[col1], subset[col2])

    if contingency.shape[0] < 2 or contingency.shape[1] < 2:
        raise ValueError("Both columns must have multiple categories")

    _, p_value, _, expected = chi2_contingency(contingency)

    if (expected < 5).any():
        raise ValueError("Chi-square test assumptions are violated")

