import binascii
import io
import gzip

def task_func(compressed_hex):
    """
    Uncompress a gzip-compressed hexadecimal string and decode it as UTF-8.

    Args:
        compressed_hex: Hex-encoded gzip-compressed data.

    Returns:
        str: Decoded UTF-8 string on success, otherwise an error message.
    """
    try:
        if compressed_hex is None:
            return "Error: input is None"

        if isinstance(compressed_hex, bytes):
            compressed_hex = compressed_hex.decode("utf-8", errors="strict")
        elif not isinstance(compressed_hex, str):
            compressed_hex = str(compressed_hex)

        hex_str = "".join(compressed_hex.split())
        if not hex_str:
            return "Error: input is empty"

        try:
            compressed_bytes = binascii.unhexlify(hex_str)
        except (binascii.Error, ValueError) as exc:
            return f"Error: invalid hexadecimal input ({exc})"

        try:
            with gzip.GzipFile(fileobj=io.BytesIO(compressed_bytes), mode="rb") as gz:
                decompressed_bytes = gz.read()
        except OSError as exc:
            return f"Error: invalid gzip data ({exc})"

        try:
            return decompressed_bytes.decode("utf-8")
        except UnicodeDecodeError as exc:
            return f"Error: decoded data is not valid UTF-8 ({exc})"

    except Exception as exc:
        return f"Error: {exc}"
