import pandas as pd

# Constants
FEATURES = ['feature1', 'feature2', 'feature3', 'feature4', 'feature5']


def task_func(df, dct):
    try:
        if not isinstance(df, pd.DataFrame) or not isinstance(dct, dict):
            return "Invalid input"

        if any(feature not in df.columns for feature in FEATURES):
            return "Invalid input"

        processed = df.copy()
        if dct:
            processed = processed.replace(dct)

        result = {}
        for feature in FEATURES:
            series = pd.to_numeric(processed[feature], errors="coerce")
            if series.empty or series.isna().any():
                return "Invalid input"

            values = series.to_numpy(dtype=float)

            mean_val = float(np.mean(values))
            median_val = float(np.median(values))
            variance_val = float(np.var(values))

            mode_res = stats.mode(values, keepdims=False)
            mode_arr = np.asarray(mode_res.mode)
            if mode_arr.size == 0:
                return "Invalid input"
            mode_val = float(mode_arr.item())

            result[feature] = {
                "mean": mean_val,
                "median": median_val,
                "mode": mode_val,
                "variance": variance_val,
            }

        return result

    except Exception:
        return "Invalid input"
