import pandas as pd
import numpy as np
from scipy.stats import chi2_contingency

def task_func(data, col1, col2):
    if not isinstance(data, pd.DataFrame) or data.empty:
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    if col1 not in data.columns or col2 not in data.columns:
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    s1 = data[col1]
    s2 = data[col2]

    def is_categorical_series(s):
        return (
            pd.api.types.is_categorical_dtype(s.dtype)
            or pd.api.types.is_object_dtype(s.dtype)
            or pd.api.types.is_string_dtype(s.dtype)
            or pd.api.types.is_bool_dtype(s.dtype)
        )

    if not is_categorical_series(s1) or not is_categorical_series(s2):
        raise TypeError("If one or both of the columns contain non-categorical data.")

    n1 = s1.nunique(dropna=True)
    n2 = s2.nunique(dropna=True)
    if n1 < 2 or n2 < 2:
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    counts1 = s1.dropna().value_counts()
    counts2 = s2.dropna().value_counts()
    if (counts1 < 5).any() or (counts2 < 5).any():
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    contingency_table = pd.crosstab(s1, s2)

    if contingency_table.shape[0] < 2 or contingency_table.shape[1] < 2:
        raise ValueError("If 'data' is empty, if 'col1' or 'col2' are not in 'data', if one or both of the columns do not have multiple categories, or if some categories have less than 5 observations (violating the chi-square test assumptions).")

    _, p_value, _, _ = chi2_contingency(contingency_table)
    return float(p_value)
