    try:
        if not isinstance(df, pd.DataFrame) or not isinstance(dct, dict):
            return "Invalid input"
        if 'feature1' not in dct:
            return "Invalid input"
        if any(feature not in df.columns for feature in FEATURES):
            return "Invalid input"

