        result = {}

        for feature in FEATURES:
            series = pd.to_numeric(replaced_df[feature], errors='coerce')
            clean = series.replace([np.inf, -np.inf], np.nan).dropna().to_numpy()

            if clean.size == 0:
                return "Invalid input"

            mean_val = float(np.mean(clean))
            median_val = float(np.median(clean))
            mode_res = stats.mode(clean, keepdims=False)
            mode_val = float(np.asarray(mode_res.mode).ravel()[0])
            variance_val = float(np.var(clean))

            result[feature] = {
                'mean': mean_val,
                'median': median_val,
                'mode': mode_val,
                'variance': variance_val,
            }

        return result
    except Exception:
        return "Invalid input"
