import pandas as pd
import re
import random

def task_func(data_list, seed=None):
    rng = random.Random(seed)

    original_strings = []
    modified_strings = []

    if data_list is None:
        return pd.DataFrame(columns=["Original String", "Modified String"])

    for item in data_list:
        original = "" if item is None else str(item)
        original_strings.append(original)

        if original == "":
            modified_strings.append("")
            continue

        # Split on commas and trim surrounding whitespace from each part.
        parts = [part.strip() for part in re.split(r"\s*,\s*", original)]

        if len(parts) == 1:
            # Nothing comma-separated to remove; removing the only value leaves an empty string.
            modified_strings.append("")
            continue

        remove_idx = rng.randrange(len(parts))
        remaining = [part for i, part in enumerate(parts) if i != remove_idx]

        modified_strings.append(", ".join(remaining))

    return pd.DataFrame(
        {
            "Original String": original_strings,
            "Modified String": modified_strings,
        }
    )
