import sqlite3
import pandas as pd
import os
import re


def task_func(db_file, table_name, column_name, pattern='\d+[xX]'):
    """
    Load all rows from an SQLite table, find regex matches in the specified column,
    and return the matches as a pandas DataFrame.
    """
    if not os.path.exists(db_file):
        raise ValueError(f"Database file does not exist: {db_file}")

    def _quote_identifier(identifier):
        return '"' + str(identifier).replace('"', '""') + '"'

    regex = re.compile(pattern)

    with sqlite3.connect(db_file) as conn:
        query = f"SELECT * FROM {_quote_identifier(table_name)}"
        df = pd.read_sql_query(query, conn)

    if column_name not in df.columns:
        raise KeyError(f"Column not found: {column_name}")

    def _extract_matches(value):
        if value is None:
            return []
        try:
            if pd.isna(value):
                return []
        except Exception:
            pass

        if isinstance(value, (list, tuple, set)):
            text = " ".join(map(str, value))
        else:
            text = str(value)

        return regex.findall(text)

    matches = df[column_name].apply(_extract_matches)

    if not matches.astype(bool).any():
        return pd.DataFrame(columns=list(df.columns) + ["matches"])

    result = df.loc[matches.astype(bool)].copy()
    result["matches"] = matches[matches.astype(bool)].values
    result = result.explode("matches", ignore_index=True)

    return result
