import os
import json
from collections import Counter

def task_func(json_files_path='./json_files/', key='name'):
    """
    Count occurrences of values for a given key across all JSON files in a directory.

    Args:
        json_files_path (str): Path to the directory containing JSON files.
        key (str): Key whose values should be counted.

    Returns:
        dict: A dictionary mapping each encountered value to its count.
    """
    counts = Counter()

    if not os.path.isdir(json_files_path):
        return {}

    for filename in os.listdir(json_files_path):
        if not filename.lower().endswith('.json'):
            continue

        file_path = os.path.join(json_files_path, filename)
        if not os.path.isfile(file_path):
            continue

        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except (OSError, json.JSONDecodeError):
            continue

        def add_value(value):
            try:
                counts[value] += 1
            except TypeError:
                counts[json.dumps(value, sort_keys=True, ensure_ascii=False)] += 1

        if isinstance(data, dict):
            if key in data:
                add_value(data[key])
        elif isinstance(data, list):
            for item in data:
                if isinstance(item, dict) and key in item:
                    add_value(item[key])

    return dict(counts)
