        if not all(isinstance(v, numbers.Real) for v in arr.flat):
            raise TypeError("Input array contains non-numeric inputs.")
    elif arr.dtype.kind not in "iufb":
        raise TypeError("Input array contains non-numeric inputs.")

    try:
        values = arr.astype(float, copy=False)
    except (TypeError, ValueError):
        raise TypeError("Input array contains non-numeric inputs.")

    if np.isnan(values).any():
        raise ValueError("Input array contains NaNs.")
    if (values < 0).any():
        raise ValueError("Input array contains negative numbers.")

    sorted_values = np.sort(values, axis=None)
    n = sorted_values.size
    x = np.arange(n)

    if n == 0:
        y = sorted_values
    else:
        total = sorted_values.sum()
        if total == 0:
            y = np.zeros_like(sorted_values, dtype=float)
        else:
            y = np.cumsum(sorted_values, dtype=float) / total

    fig, ax = plt.subplots()
    ax.plot(x, y, marker="o", linestyle="-")
    ax.set_title("Cumulative Probability Plot")
    ax.set_xlabel("Index")
    ax.set_ylabel("Cumulative Probability")
