    weather_conditions=['Sunny', 'Cloudy', 'Rainy', 'Snowy', 'Stormy'],
    timezones={
        'New York': 'America/New_York',
        'London': 'Europe/London',
        'Beijing': 'Asia/Shanghai',
        'Tokyo': 'Asia/Tokyo',
        'Sydney': 'Australia/Sydney'
    },
    seed=42
):
    # Validate utc_datetime
    if not isinstance(utc_datetime, datetime):
        raise ValueError("utc_datetime must be a datetime object")

    # Validate seed
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise ValueError("seed must be an integer")

    # Validate cities
    if not isinstance(cities, list) or len(cities) == 0 or any(not isinstance(city, str) for city in cities):
        raise ValueError("cities must be a non-empty list of strings")

    # Validate weather conditions
    if (
        not isinstance(weather_conditions, list)
        or len(weather_conditions) == 0
        or any(not isinstance(condition, str) for condition in weather_conditions)
    ):
        raise ValueError("weather_conditions must be a non-empty list of strings")

    # Validate timezones mapping
    if not isinstance(timezones, dict) or any(
        not isinstance(k, str) or not isinstance(v, str) for k, v in timezones.items()
    ):
        raise ValueError("timezones must be a dictionary mapping city names to timezone strings")

    # Ensure all requested cities have defined timezones and valid timezone names
    validated_timezones = {}
    for city in cities:
        if city not in timezones:
            raise ValueError(f"Missing timezone for city: {city}")
        tz_name = timezones[city]
        try:
            validated_timezones[city] = pytz.timezone(tz_name)
        except Exception as exc:
            raise ValueError(f"Invalid timezone for city '{city}': {tz_name}") from exc

    # Convert input datetime to UTC
    if utc_datetime.tzinfo is None:
        utc_dt = pytz.utc.localize(utc_datetime)
    else:
        utc_dt = utc_datetime.astimezone(pytz.utc)

    # Deterministic weather selection
    set_seed(seed)

    rows = []
    for city in cities:
        local_dt = utc_dt.astimezone(validated_timezones[city])
        weather = weather_conditions[randint(0, len(weather_conditions) - 1)]
        rows.append(
            {
                "City": city,
                "Local Time": local_dt.strftime("%Y-%m-%d %H:%M:%S %Z"),
                "Weather Condition": weather,
            }
        )

    return pd.DataFrame(rows, columns=["City", "Local Time", "Weather Condition"])
