from datetime import datetime
import matplotlib.pyplot as plt
import pandas as pd


def task_func(data):
    df = data.copy() if isinstance(data, pd.DataFrame) else pd.DataFrame(data)

    if df.empty:
        fig, ax = plt.subplots()
        ax.set_title(f"Monthly Data for {datetime.now().year}")
        ax.set_xlabel("Month")
        ax.set_ylabel("Value")
        return ax

    def infer_year(frame: pd.DataFrame) -> int:
        if "year" in frame.columns:
            years = pd.to_numeric(frame["year"], errors="coerce").dropna()
            if not years.empty:
                return int(years.iloc[0])

        if isinstance(frame.index, pd.DatetimeIndex) and len(frame.index) > 0:
            return int(frame.index[0].year)

        for col in ("date", "datetime", "timestamp"):
            if col in frame.columns:
                dates = pd.to_datetime(frame[col], errors="coerce").dropna()
                if not dates.empty:
                    return int(dates.iloc[0].year)

        if "month" in frame.columns:
            dates = pd.to_datetime(frame["month"], errors="coerce").dropna()
            if not dates.empty:
                return int(dates.iloc[0].year)

        return datetime.now().year

    def select_columns(frame: pd.DataFrame):
        month_col = "month" if "month" in frame.columns else None
        value_col = "value" if "value" in frame.columns else None

        if month_col is None or value_col is None:
            cols = list(frame.columns)
            if len(cols) < 2:
                raise ValueError("Input data must contain at least month and value data.")
            if month_col is None:
                month_col = cols[0]
            if value_col is None:
                value_col = cols[1] if cols[1] != month_col else (cols[2] if len(cols) > 2 else cols[0])

        return month_col, value_col

    year = infer_year(df)
    month_col, value_col = select_columns(df)

    plot_df = df[[month_col, value_col]].copy()
    plot_df = plot_df.dropna(subset=[month_col, value_col])

    month_series = plot_df[month_col]
    sort_key = None
    labels = month_series.astype(str)

    if pd.api.types.is_datetime64_any_dtype(month_series):
        sort_key = month_series.dt.month
        labels = month_series.dt.strftime("%b")
    else:
        parsed_months = pd.to_datetime(month_series, errors="coerce")
        if parsed_months.notna().any():
            sort_key = parsed_months.dt.month
            labels = parsed_months.dt.strftime("%b")
        else:
            numeric_months = pd.to_numeric(month_series, errors="coerce")
            if numeric_months.notna().any():
                sort_key = numeric_months
                if (numeric_months.dropna() % 1 == 0).all():
                    labels = numeric_months.astype("Int64").astype(str)
                else:
                    labels = numeric_months.astype(str)

    if sort_key is not None:
        plot_df = plot_df.assign(_sort_key=sort_key, _label=labels).sort_values("_sort_key")
        x = plot_df["_label"].astype(str).tolist()
        y = plot_df[value_col].tolist()
    else:
        x = labels.tolist()
        y = plot_df[value_col].tolist()

    fig, ax = plt.subplots()
    ax.bar(x, y)
    ax.set_title(f"Monthly Data for {year}")
    ax.set_xlabel("Month")
    ax.set_ylabel("Value")

    return ax
